          refreshToken == other.refreshToken &&
          error == other.error &&
          needsUiaa == other.needsUiaa &&
          session == other.session &&
          flows == other.flows;
}

class ChatMessage {
  final String id;
  final String senderId;
  final String senderName;
  final String content;

  /// Sanitized Matrix HTML for text-like messages.
  final String? formattedBody;
  final String? caption;

  /// Sanitized Matrix HTML for media captions.
  final String? captionFormattedBody;

  /// Intentional mentions carried by `m.mentions`.
  final List<String> mentionedUserIds;
  final bool mentionsRoom;
  final String timestamp;
  final bool isMe;
  final MessageType msgType;
  final String? imageUrl;

  /// Serialized Matrix MediaSource. Required to download encrypted media.
  final String? mediaSourceJson;
  final int? imageWidth;
  final int? imageHeight;

  /// Original filename for file/audio attachments.
  final String? filename;

  /// Declared file size in bytes for file/audio attachments.
  final int? fileSize;

  /// RFC 5870 geo URI for location messages (e.g. `geo:lat,lng`).
  final String? geoUri;

  /// Poll data when `msg_type == Poll`.
  final PollInfo? poll;

  /// Event ID this message is replying to, if any.
  final String? inReplyTo;

  /// Whether this message has been edited.
  final bool isEdited;

  /// History of edits (previous versions), oldest first.
  final List<String> editHistory;

  /// Emoji reactions on this message, one entry per distinct key.
  final List<Reaction> reactions;

  /// Members who have read up to this message (only populated for the
  /// current user's own messages; empty otherwise).
  final List<MessageReader> readers;

  /// Total joined member count of the room (including the current user).
  final int totalMembers;

  const ChatMessage({
    required this.id,
    required this.senderId,
    required this.senderName,
    required this.content,
    this.formattedBody,
    this.caption,
    this.captionFormattedBody,
    required this.mentionedUserIds,
    required this.mentionsRoom,
    required this.timestamp,
    required this.isMe,
    required this.msgType,
    this.imageUrl,
    this.mediaSourceJson,
    this.imageWidth,
    this.imageHeight,
    this.filename,
    this.fileSize,
    this.geoUri,
    this.poll,
    this.inReplyTo,
    required this.isEdited,
    required this.editHistory,
    required this.reactions,
    required this.readers,
    required this.totalMembers,
  });

  @override
  int get hashCode =>
      id.hashCode ^
      senderId.hashCode ^
      senderName.hashCode ^
      content.hashCode ^
      formattedBody.hashCode ^
      caption.hashCode ^
      captionFormattedBody.hashCode ^
      mentionedUserIds.hashCode ^
      mentionsRoom.hashCode ^
      timestamp.hashCode ^
      isMe.hashCode ^
      msgType.hashCode ^
      imageUrl.hashCode ^
      mediaSourceJson.hashCode ^
      imageWidth.hashCode ^
      imageHeight.hashCode ^
      filename.hashCode ^
      fileSize.hashCode ^
      geoUri.hashCode ^
      poll.hashCode ^
      inReplyTo.hashCode ^
      isEdited.hashCode ^
      editHistory.hashCode ^
      reactions.hashCode ^
      readers.hashCode ^
      totalMembers.hashCode;

  @override
  bool operator ==(Object other) =>
      identical(this, other) ||
      other is ChatMessage &&
          runtimeType == other.runtimeType &&
          id == other.id &&
          senderId == other.senderId &&
          senderName == other.senderName &&
          content == other.content &&
          formattedBody == other.formattedBody &&
          caption == other.caption &&
          captionFormattedBody == other.captionFormattedBody &&
          mentionedUserIds == other.mentionedUserIds &&
          mentionsRoom == other.mentionsRoom &&
          timestamp == other.timestamp &&
          isMe == other.isMe &&
          msgType == other.msgType &&
          imageUrl == other.imageUrl &&
          mediaSourceJson == other.mediaSourceJson &&
          imageWidth == other.imageWidth &&
          imageHeight == other.imageHeight &&
          filename == other.filename &&
          fileSize == other.fileSize &&
          geoUri == other.geoUri &&
          poll == other.poll &&
          inReplyTo == other.inReplyTo &&
          isEdited == other.isEdited &&
          editHistory == other.editHistory &&
          reactions == other.reactions &&
          readers == other.readers &&
          totalMembers == other.totalMembers;
}

class ChatRoom {
